DECLARE
    @CompatAntes INT,
    @CompatDepois INT,
    @LegacyCEAntes BIT,
    @LegacyCEDepois BIT,
    @OptimizerHotfixesAntes BIT,
    @OptimizerHotfixesDepois BIT,
    @QueryStoreAntes NVARCHAR(60),
    @QueryStoreDepois NVARCHAR(60),
    @MensagemErro NVARCHAR(MAX),
    @Sucesso BIT = 1;

-- Estado antes
SELECT
    @CompatAntes = compatibility_level
FROM sys.databases
WHERE name = DB_NAME();

SELECT
    @LegacyCEAntes = CONVERT(BIT, value)
FROM sys.database_scoped_configurations
WHERE name = 'LEGACY_CARDINALITY_ESTIMATION';

SELECT
    @OptimizerHotfixesAntes = CONVERT(BIT, value)
FROM sys.database_scoped_configurations
WHERE name = 'QUERY_OPTIMIZER_HOTFIXES';

SELECT
    @QueryStoreAntes = actual_state_desc
FROM sys.database_query_store_options;

BEGIN TRY

    IF CONVERT(INT, SERVERPROPERTY('ProductMajorVersion')) < 14
    BEGIN
        RAISERROR(
            'SQL Server abaixo de 2017. MigraÃ§Ã£o para compatibilidade 140 nÃ£o aplicada.',
            16,
            1
        );
    END;

    ALTER DATABASE CURRENT
    SET COMPATIBILITY_LEVEL = 140;

    ALTER DATABASE SCOPED CONFIGURATION
    SET LEGACY_CARDINALITY_ESTIMATION = ON;

    ALTER DATABASE SCOPED CONFIGURATION
    SET QUERY_OPTIMIZER_HOTFIXES = ON;

END TRY
BEGIN CATCH

    SET @Sucesso = 0;
    SET @MensagemErro = ERROR_MESSAGE();

END CATCH;

-- Estado depois
SELECT
    @CompatDepois = compatibility_level
FROM sys.databases
WHERE name = DB_NAME();

SELECT
    @LegacyCEDepois = CONVERT(BIT, value)
FROM sys.database_scoped_configurations
WHERE name = 'LEGACY_CARDINALITY_ESTIMATION';

SELECT
    @OptimizerHotfixesDepois = CONVERT(BIT, value)
FROM sys.database_scoped_configurations
WHERE name = 'QUERY_OPTIMIZER_HOTFIXES';

SELECT
    @QueryStoreDepois = actual_state_desc
FROM sys.database_query_store_options;

INSERT INTO dbo.SIS_MigracaoCompatibilidadeSql
(
    NomeBanco,
    Servidor,
    VersaoSql,
    CompatAntes,
    CompatDepois,
    LegacyCEAntes,
    LegacyCEDepois,
    OptimizerHotfixesAntes,
    OptimizerHotfixesDepois,
    QueryStoreAntes,
    QueryStoreDepois,
    Sucesso,
    MensagemErro
)
VALUES
(
    DB_NAME(),
    @@SERVERNAME,
    CONVERT(NVARCHAR(128), SERVERPROPERTY('ProductVersion')),
    @CompatAntes,
    @CompatDepois,
    @LegacyCEAntes,
    @LegacyCEDepois,
    @OptimizerHotfixesAntes,
    @OptimizerHotfixesDepois,
    @QueryStoreAntes,
    @QueryStoreDepois,
    @Sucesso,
    @MensagemErro
);

IF @Sucesso = 0
BEGIN
    THROW 50000, @MensagemErro, 1;
END;
